namespace eval connect {
    namespace export winner

    proc winner {board} {
        set matrix [lmap row $board {split [string trim $row]}]

        set winner ""
        if {[checkWinner $matrix O]} {
            set winner O
        } elseif {[checkWinner [transpose $matrix] X]} {
            set winner X
        }

        return $winner
    }

    proc transpose {matrix} {
        set transposed {}
        set width [llength [lindex $matrix 0]]
        for {set i 0} {$i < $width} {incr i} {
            lappend transposed [lmap row $matrix {lindex $row $i}]
        }
        return $transposed
    }

    proc checkWinner {matrix player} {
        # assume square
        set width [llength $matrix]

        set stack {}

        # my pieces in the top row
        for {set c 0} {$c < $width} {incr c} {
            if {[lindex $matrix 0 $c] eq $player} {
                lappend stack [list 0 $c]
            }
        }
        if {[llength $stack] == 0} {
            return false
        }
        if {$width == 1} {
            return true
        }

        while {[llength $stack] > 0} {
            lassign [lindex $stack end] r c
            set stack [lrange $stack 0 end-1]
            foreach pos [myNeighbours $matrix $player $r $c] {
                lassign $pos rr cc
                if {$rr == $width - 1} {
                    # I have a neighbour in the last row
                    return true
                }
                lset matrix $r $c "seen"  ;# no backtracking
                lappend stack [list $rr $cc]
            }
        }

        return false
    }

    proc myNeighbours {matrix player r c} {
        set width [llength $matrix]
        set neighbours {}
        foreach dr {-1 0 1} {
            foreach dc {-1 0 1} {
                if {$dr == $dc} then continue
                set rr [expr {$r + $dr}]
                set cc [expr {$c + $dc}]
                if {0 <= $rr && $rr < $width &&
                    0 <= $cc && $cc < $width &&
                    [lindex $matrix $rr $cc] eq $player
                } {
                    lappend neighbours [list $rr $cc]
                }
            }
        }
        return $neighbours
    }
}

namespace import connect::winner

test_code:
#!/usr/bin/env tclsh
package require tcltest
namespace import ::tcltest::*
source testHelpers.tcl

############################################################
source "connect.tcl"

test connect-1 "an empty board has no winner" -body {
    winner {
        ". . . . ."
        " . . . . ."
        "  . . . . ."
        "   . . . . ."
        "    . . . . ."
    }
} -returnCodes ok -result ""

skip connect-2
test connect-2 "X can win on a 1x1 board" -body {
    winner {
        "X"
    }
} -returnCodes ok -result "X"

skip connect-3
test connect-3 "O can win on a 1x1 board" -body {
    winner {
        "O"
    }
} -returnCodes ok -result "O"

skip connect-4
test connect-4 "only edges does not make a winner" -body {
    winner {
        "O O O X"
        " X . . X"
        "  X . . X"
        "   X O O O"
    }
} -returnCodes ok -result ""

skip connect-5
test connect-5 "illegal diagonal does not make a winner" -body {
    winner {
        "X O . ."
        " O X X X"
        "  O X O ."
        "   . O X ."
        "    X X O O"
    }
} -returnCodes ok -result ""

skip connect-6
test connect-6 "nobody wins crossing adjacent angles" -body {
    winner {
        "X . . ."
        " . X O ."
        "  O . X O"
        "   . O . X"
        "    . . O ."
    }
} -returnCodes ok -result ""

skip connect-7
test connect-7 "X wins crossing from left to right" -body {
    winner {
        ". O . ."
        " O X X X"
        "  O X O ."
        "   X X O X"
        "    . O X ."
    }
} -returnCodes ok -result "X"

skip connect-11
test connect-11 "X wins with left-hand dead end fork" -body {
    winner {
        ". . X ."
        " X X . ."
        "  . X X X"
        "   O O O O"
    }
} -returnCodes ok -result "X"

skip connect-12
test connect-12 "X wins with right-hand dead end fork" -body {
    winner {
        ". . X X"
        " X X . ."
        "  . X X ."
        "   O O O O"
    }
} -returnCodes ok -result "X"

skip connect-8
test connect-8 "O wins crossing from top to bottom" -body {
    winner {
        ". O . ."
        " O X X X"
        "  O O O ."
        "   X X O X"
        "    . O X ."
    }
} -returnCodes ok -result "O"

skip connect-9
test connect-9 "X wins using a convoluted path" -body {
    winner {
        ". X X . ."
        " X . X . X"
        "  . X . X ."
        "   . X X . ."
        "    O O O O O"
    }
} -returnCodes ok -result "X"

skip connect-10
test connect-10 "X wins using a spiral path" -body {
    winner {
        "O X X X X X X X X"
        " O X O O O O O O O"
        "  O X O X X X X X O"
        "   O X O X O O O X O"
        "    O X O X X X O X O"
        "     O X O O O X O X O"
        "      O X X X X X O X O"
        "       O O O O O O O X O"
        "        X X X X X X X X O"
    }
} -returnCodes ok -result "X"


